export function getRJMLAProfile(acNo: number): MLAProfile | undefined {
  return RJ_MLA_PROFILES.find(p => p.acNo === acNo);
}

export function getRJMLAsByParty(party: string): MLAProfile[] {
  return RJ_MLA_PROFILES.filter(p => p.party === party);
}

export function getRJFemaleMLAs(): MLAProfile[] {
  return RJ_MLA_PROFILES.filter(p => p.gender === 'F');
}
